package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.domain.protocol.*;
import com.lianxibu.site.repository.jobs.*;
import com.lianxibu.site.service.jobs.GenerationFlowService.*;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import tools.jackson.databind.node.ObjectNode;
/** Actual original scope input and native writer/save/receipt. Source/model/settings genesis is explicitly fictional. */
class ReportPreparedReceiptTest {
 boolean mysql(){return false;}
 ReportInputWriterAdmissionTest.Period x;ReportPreparationInputProfile.Complete profile;GenerationFlowService.Frozen input;GenerationJdbcStore store;JdbcReportPreparedInputs receipts;
 void setup(){x=new ReportInputWriterAdmissionTest(){@Override boolean mysql(){return ReportPreparedReceiptTest.this.mysql();}}.admitted();profile=ReportPreparationInputProfile.create(x.captured(),new FrozenGenerationSettings(1,List.of(),List.of()),"fictional-prepared-period-report",null,false);var base=x.nativeData().f.h.h.f;String root=JdbcReportPreparedInputs.root(x.captured().scope().logicalKey(),x.captured().scope().generation());Instant now=x.captured().cutoff().plusNanos(123456000);var command=profile.command();String hash=CanonicalJson.hash(CanonicalJson.Domain.INPUT,CanonicalJson.parse(profile.snapshotJson()));String request="{\"provider\":\"fictional\",\"model\":\"fictional\",\"input_hash\":\""+hash+"\",\"messages\":[{\"role\":\"user\",\"content\":\"Fictional original period\"}],\"response_format\":{},\"parameters\":{},\"schema_version\":\"1\",\"prompt_version\":\"1\"}";request=JdbcFrozenInputs.canonical(CanonicalJson.parse(request));var snapshot=CanonicalJson.parse(profile.snapshotJson());input=new Frozen(root,command.logicalKey(),command.generation(),command.stage(),x.captured().cutoff(),snapshot.get("coverage_state").asText(),snapshot.get("missing").valueStream().map(v->v.asText()).toList(),profile.snapshotJson(),hash,request,command.stage().priority(),now,"queued");store=new GenerationJdbcStore(base.source,Clock.fixed(now,ZoneOffset.UTC),JdbcReportPreparedInputs.ACTOR,root,command);receipts=new JdbcReportPreparedInputs(base.source);}
 void save(){ReportOriginalCompletionTest.utc(()->{var base=x.nativeData().f.h.h.f;return base.writes.execute(new SharedWriteExecutor.ActionContext(JdbcReportPreparedInputs.action(input.ownerId()),input.ownerId(),input.inputHash()),k->null,a->{x.admission().asWriterSource(x.captured()).snapshot(profile.command(),x.captured().cutoff());store.save(input,JdbcReportPreparedInputs.action(input.ownerId()));return input;});});}
 JdbcReportPreparedInputs.Receipt read(){return x.nativeData().rr(()->receipts.read(input.ownerId()));}
 @Test void ActualOriginalFullInputPreparationProducesExactNativeReceiptAndReplay(){setup();assertNull(read());save();var result=read();assertEquals(input.ownerId(),result.rootId());assertEquals(input.inputHash(),result.inputHash());assertEquals("queued",result.state());assertEquals(input.eligibleAt(),result.recordedAt());ReportOriginalCompletionTest.utc(()->x.nativeData().rr(()->{assertEquals(input,store.committed(JdbcReportPreparedInputs.action(input.ownerId())));return true;}));assertEquals(1,x.nativeData().f.h.h.f.sends);}
 @Test void WrongProgramActorNativeRoleOrHashRejectEvenWhenPayloadStillValid(){setup();save();var jdbc=x.nativeData().f.h.h.f.jdbc;String id=JdbcFrozenInputs.stableId("prepare-action",JdbcReportPreparedInputs.action(input.ownerId()));for(String column:List.of("operator_id","task_kind","target_id")){String old=jdbc.queryForObject("SELECT "+column+" FROM jobs WHERE id=?",String.class,id);jdbc.update("UPDATE jobs SET "+column+"='fictional-damage' WHERE id=?",id);assertThrows(RuntimeException.class,this::read);jdbc.update("UPDATE jobs SET "+column+"=? WHERE id=?",old,id);}jdbc.update("UPDATE jobs SET action_payload_hash=UNHEX(?) WHERE id=?","0".repeat(64),id);assertThrows(RuntimeException.class,this::read);}
 @Test void RehashedCommandPayloadAndNativeTimeCannotImplyANewInputOrAttempt(){setup();save();var jdbc=x.nativeData().f.h.h.f.jdbc;String id=JdbcFrozenInputs.stableId("prepare-action",JdbcReportPreparedInputs.action(input.ownerId()));var changed=(ObjectNode)CanonicalJson.parse(read().payloadJson());changed.put("owner_id","fictional-other-root");String raw=JdbcFrozenInputs.canonical(changed);jdbc.update("UPDATE jobs SET action_payload=?,action_payload_hash=? WHERE id=?",raw,JdbcGenerationLineage.hash(raw),id);assertThrows(RuntimeException.class,this::read);setup();save();jdbc=x.nativeData().f.h.h.f.jdbc;id=JdbcFrozenInputs.stableId("prepare-action",JdbcReportPreparedInputs.action(input.ownerId()));final String targetId=id;final var update=jdbc;update.update("UPDATE jobs SET acted_at=? WHERE id=?",ps->{ps.setTimestamp(1,java.sql.Timestamp.from(input.eligibleAt().plusSeconds(1)),Calendar.getInstance(TimeZone.getTimeZone("UTC")));ps.setString(2,targetId);});assertThrows(RuntimeException.class,this::read);}
 @Test void OriginalUnknownCapacityReadonlyAndColdBoundariesDoNotGrantPreparationPermission(){setup();var ds=org.mockito.Mockito.mock(javax.sql.DataSource.class);new JdbcReportPreparedInputs(ds);org.mockito.Mockito.verifyNoInteractions(ds);assertThrows(RuntimeException.class,()->receipts.read(input.ownerId()));save();var id=JdbcFrozenInputs.stableId("prepare-action",JdbcReportPreparedInputs.action(input.ownerId()));x.nativeData().f.h.h.f.jdbc.update("UPDATE jobs SET action_payload=? WHERE id=?",JdbcFrozenInputs.canonical(tools.jackson.databind.json.JsonMapper.shared().createObjectNode().put("fictional_over_capacity","x".repeat(65537))),id);assertThrows(RuntimeException.class,this::read);assertTrue(input.toString().contains("Frozen"));}
}
